package it.financemanager.application.service;
import it.financemanager.application.exception.ResourceNotFoundException; import it.financemanager.application.port.in.BudgetUseCase; import it.financemanager.application.port.out.*; import it.financemanager.domain.model.Budget; import java.math.BigDecimal; import java.time.LocalDate; import java.util.List;
public final class BudgetService implements BudgetUseCase { private final BudgetPort budgets;private final CategoryPort categories;private final UserResolver users;public BudgetService(BudgetPort b,CategoryPort c,CurrentActorPort a,UserPort u){budgets=b;categories=c;users=new UserResolver(a,u);}public List<Budget> list(){return budgets.findAllByUser(users.current().id());}public Budget get(Long id){return find(id,users.current().id());}public Budget create(Long cid,BigDecimal amount,LocalDate start,LocalDate end){validate(start,end);Long uid=users.current().id();category(cid,uid);return budgets.create(uid,cid,amount,start,end);}public Budget update(Long id,Long cid,BigDecimal amount,LocalDate start,LocalDate end){validate(start,end);Long uid=users.current().id();category(cid,uid);return budgets.update(find(id,uid),cid,amount,start,end);}public void delete(Long id){budgets.delete(find(id,users.current().id()));}private void validate(LocalDate s,LocalDate e){if(s.isAfter(e))throw new IllegalArgumentException("startDate must not be after endDate");}private void category(Long id,Long uid){categories.findByIdAndUser(id,uid).orElseThrow(()->new ResourceNotFoundException("Category",id));}private Budget find(Long id,Long uid){return budgets.findByIdAndUser(id,uid).orElseThrow(()->new ResourceNotFoundException("Budget",id));}}
